        {:ok, new_pos, _text, _capture} -> {:ok, new_pos, ref_stack, []}
        :fail -> :fail
      end
    end

    def parse_expr__844(stream, pos, ref_stack, context) do
      Parser.star(&parse_expr__845/4, stream, pos, ref_stack, context)
    end

    def parse_expr__846(stream, pos, ref_stack, _context) do
      case Parser.match_token(stream, pos, :INTEGER) do
        {:ok, new_pos, text, nil} -> {:ok, new_pos, ref_stack, n: {:token, :INTEGER, text}}
        {:ok, new_pos, _text, capture} -> {:ok, new_pos, ref_stack, n: capture}
        :fail -> :fail
      end
    end

    def parse_expr__848(stream, pos, ref_stack, _context) do
      case Parser.match_token(stream, pos, :TRIVIA) do
        {:ok, new_pos, _text, _capture} -> {:ok, new_pos, ref_stack, []}
        :fail -> :fail
      end
    end

    def parse_expr__847(stream, pos, ref_stack, context) do
      Parser.star(&parse_expr__848/4, stream, pos, ref_stack, context)
    end

    def parse_expr__850(stream, pos, ref_stack, context) do
      case parse_rule__offset_clause(stream, pos, ref_stack, context) do
        {:ok, new_pos, new_ref_stack, sub_captures} ->
          {:ok, new_pos, new_ref_stack, offset_clause: {:rule, :offset_clause, sub_captures}}

        _fail ->
          :fail
      end
    end

    def parse_expr__849(stream, pos, ref_stack, context) do
      Parser.opt(&parse_expr__850/4, stream, pos, ref_stack, context)
    end

    def parse_rule__limit_clause(stream, pos, ref_stack, context) do
      with {:ok, pos1, ref1, cap0} <- parse_expr__843(stream, pos, ref_stack, context),
           {:ok, pos2, ref2, cap1} <- parse_expr__844(stream, pos1, ref1, context),
           {:ok, pos3, ref3, cap2} <- parse_expr__846(stream, pos2, ref2, context),
           {:ok, pos4, ref4, cap3} <- parse_expr__847(stream, pos3, ref3, context),
           {:ok, pos5, ref5, cap4} <- parse_expr__849(stream, pos4, ref4, context) do
        {:ok, pos5, ref5,
         Parser.merge_captures(
           cap0,
           Parser.merge_captures(
             cap1,
             Parser.merge_captures(cap2, Parser.merge_captures(cap3, cap4))
           )
         )}
      else
        _fail -> :fail
      end
    end

    (
      @doc "Tokenizes `input` completely via maximal munch, applies any `@keywords`/`@refine` rules, or reports the first position nothing matches. `context` is read-only and only ever consulted by a `Grammar.IR.CustomLexeme` `@native(...)` token, if the grammar has one."
      @spec tokenize(String.t(), term()) :: {:ok, [Token.t()]} | {:error, Ichor.Error.t()}
      def tokenize(input, context \\ nil) do
        with {:ok, input} <- Grammar.Source.validate(input),
             {:ok, raw_tokens} <-
               Tokenizer.tokenize(fn inp -> lex_candidates(inp, context) end, input) do
          Grammar.Lexer.reclassify(raw_tokens, %{
            IDENT:
              {:custom, Scry.Core.Grammar.KeywordRefiner, :refine,
               [
                 :KW_SELECT,
                 :KW_WHERE,
                 :KW_AND,
                 :KW_OR,
                 :KW_NOT,
                 :KW_IN,
                 :KW_NIL,
                 :KW_TRUE,
                 :KW_FALSE,
                 :KW_GROUP,
                 :KW_BY,
                 :KW_HAVING,
                 :KW_DISTINCT,
                 :KW_ORDER,
                 :KW_LIMIT,
                 :KW_OFFSET,
                 :KW_DESC,
                 :KW_ASC,
                 :KW_REQUIRED,
                 :KW_IF,
                 :KW_WHEN,
                 :KW_THEN,
                 :KW_ELSE,
                 :KW_FRAGMENT,
                 :KW_WITH,
                 :KW_UNION,
                 :KW_ALL,
                 :KW_INTERSECT,
                 :KW_EXCEPT,
                 :KW_OVER,
                 :KW_PARTITION,
                 :KW_ROWS,
                 :KW_BETWEEN,
                 :KW_PRECEDING,
                 :KW_FOLLOWING,
                 :KW_CURRENT,
                 :KW_ROW,
                 :KW_UNBOUNDED,
                 :KW_TYPE,
                 :KW_ROLLUP,
                 :KW_CUBE,
                 :KW_SUBSET,
                 :KW_SUPERSET,
                 :KW_OF,
                 :KW_EQUAL,
                 :KW_TO,
                 :KW_RECURSIVE
               ]}
          })
        end
      end
    )

    @doc "Matches `input` against the grammar's root rule, requiring the entire (tokenized) input to be consumed. A bare recognizer -- no `Ichor.Actions` involved. `context` is read-only and only ever consulted by a `Grammar.IR.Custom` `@native(...)` node, if the grammar has one."
    @spec parse(String.t(), term()) ::
            {:ok, non_neg_integer(), Ichor.Capture.raw_captures()} | {:error, Ichor.Error.t()}
    def parse(input, context \\ nil) do
      with {:ok, tokens} <- tokenize(input, context) do
        stream = List.to_tuple(tokens)

        case parse_rule__document(stream, 0, [0], context) do
          {:ok, pos, _ref_stack, raw_captures} when pos == tuple_size(stream) ->
            {:ok, pos, raw_captures}

          {:ok, pos, _ref_stack, _raw_captures} ->
            {:error, Parser.unexpected_token_error(stream, pos, input)}

          _fail ->
            {:error,
             Ichor.Error.new(
               message: "input does not match #{inspect(:document)}",
               stage: :parser,
               source: input
             )}
        end
      end
    end

    @doc "Like `parse/1`, but runs the match through the compile-time-known Actions module, returning the grammar's actual evaluated result."
    @spec run(String.t(), Ichor.Actions.context()) ::
            {:ok, term()} | {:error, Ichor.Error.t() | [Ichor.Error.t()]}
    def run(input, initial_context \\ nil) do
      with {:ok, _pos, raw_captures} <- parse(input, initial_context),
           {:ok, value, _context} <-
             Ichor.Actions.evaluate(
               :document,
               raw_captures,
               Scry.Core.Actions,
               initial_context,
               %{
                 power: MapSet.new([]),
                 body_list_tail: MapSet.new([]),
                 literal_list: MapSet.new([:tail, :COMMA]),
                 call_with_path: MapSet.new([]),
                 bitwise_tail: MapSet.new([]),
                 document: MapSet.new([:type_or_comment, :fragment_or_comment, :with_or_comment]),
                 call: MapSet.new([]),
                 goal_args: MapSet.new([]),
                 combined_select: MapSet.new([:combinator_tail]),
                 if_clause: MapSet.new([]),
                 type_decl: MapSet.new([]),
                 predicate_lhs: MapSet.new([]),
                 group_by_clause: MapSet.new([]),
                 additive_tail: MapSet.new([]),
                 body_item_ep1: MapSet.new([]),
                 qualified_call_with_path: MapSet.new([]),
                 body_item: MapSet.new([]),
                 type_field: MapSet.new([]),
                 list: MapSet.new([]),
                 field_body_item: MapSet.new([]),
                 order_item_list: MapSet.new([:tail, :COMMA]),
                 when_clause: MapSet.new([]),
                 when_expr: MapSet.new([:when_clause]),
                 where_clause: MapSet.new([]),
                 predicate: MapSet.new([]),
                 rational: MapSet.new([]),
                 additive: MapSet.new([:additive_tail]),
                 primary: MapSet.new([]),
                 comp_op: MapSet.new([]),
                 mult_tail: MapSet.new([]),
                 shape_type: MapSet.new([]),
                 unary: MapSet.new([]),
                 subset_of_op: MapSet.new([]),
                 multiplicative: MapSet.new([:mult_tail]),
                 partition_clause: MapSet.new([]),
                 conjunction: MapSet.new([:right, :KW_AND]),
                 qualified_call: MapSet.new([]),
                 base_type: MapSet.new([]),
                 type_field_list: MapSet.new([:tail, :COMMA]),
                 superset_of_op: MapSet.new([]),
                 select: MapSet.new([]),
                 spread: MapSet.new([]),
                 subset_or_eq_op: MapSet.new([]),
                 path: MapSet.new([:tail, :DOT]),
                 in_lhs: MapSet.new([]),
                 fragment_or_comment: MapSet.new([]),
                 type_operand: MapSet.new([]),
                 type_kind: MapSet.new([]),
                 order_item: MapSet.new([]),
                 group_by_rollup: MapSet.new([]),
                 call_arg: MapSet.new([]),
                 type_param: MapSet.new([]),
                 superset_or_eq_op: MapSet.new([]),
                 union_tail: MapSet.new([]),
                 negation: MapSet.new([]),
                 frame_bound: MapSet.new([]),
                 disjunction: MapSet.new([:right, :KW_OR]),
                 distinct_clause: MapSet.new([]),
                 select_ep1a: MapSet.new([]),
                 having_clause: MapSet.new([]),
                 body_list_sep: MapSet.new([]),
                 group_by_cube: MapSet.new([]),
                 offset_clause: MapSet.new([]),
                 frame_clause: MapSet.new([]),
                 body_list: MapSet.new([]),
                 literal: MapSet.new([]),
                 comparison_ep1e: MapSet.new([]),
                 order_by_clause: MapSet.new([]),
                 field_name: MapSet.new([]),
                 call_args: MapSet.new([:tail, :COMMA]),
                 with_or_comment: MapSet.new([]),
                 field_list: MapSet.new([:tail, :COMMA]),
                 type_or_comment: MapSet.new([]),
                 required_clause: MapSet.new([]),
                 with_decl: MapSet.new([]),
                 expression: MapSet.new([:bitwise_tail]),
                 window_call: MapSet.new([]),
                 over_spec: MapSet.new([]),
                 fragment_decl: MapSet.new([]),
                 comparison: MapSet.new([]),
                 type_expr: MapSet.new([:union_tail]),
                 combinator_tail: MapSet.new([]),
                 list_type: MapSet.new([]),
                 limit_clause: MapSet.new([])
               }
             ) do
        {:ok, value}
      end
    end

    @doc "Like `run/2`, but evaluates `input` as a sequence of top-level matches against the root rule, one after another, threading context from each into the next (loading a standard-library file one top-level form at a time is the motivating case -- most grammars only ever need `run/2`)."
    @spec run_sequence(String.t(), Ichor.Actions.context()) ::
            {:ok, [term()], Ichor.Actions.context()}
            | {:error, Ichor.Error.t() | [Ichor.Error.t()]}
    def run_sequence(input, initial_context) do
      with {:ok, tokens} <- tokenize(input, initial_context) do
        do_run_sequence(List.to_tuple(tokens), 0, initial_context, [])
      end
    end

    def do_run_sequence(stream, pos, ctx, acc) do
      pos = Parser.skip_leading_trivia(stream, pos, :TRIVIA)

      if pos >= tuple_size(stream) do
        {:ok, Enum.reverse(acc), ctx}
      else
        case parse_rule__document(stream, pos, [0], ctx) do
          {:ok, new_pos, _ref_stack, raw_captures} ->
            case Ichor.Actions.evaluate(:document, raw_captures, Scry.Core.Actions, ctx, %{
                   power: MapSet.new([]),
                   body_list_tail: MapSet.new([]),
                   literal_list: MapSet.new([:tail, :COMMA]),
                   call_with_path: MapSet.new([]),
                   bitwise_tail: MapSet.new([]),
                   document:
                     MapSet.new([:type_or_comment, :fragment_or_comment, :with_or_comment]),
                   call: MapSet.new([]),
                   goal_args: MapSet.new([]),
                   combined_select: MapSet.new([:combinator_tail]),
                   if_clause: MapSet.new([]),
                   type_decl: MapSet.new([]),
                   predicate_lhs: MapSet.new([]),
                   group_by_clause: MapSet.new([]),
                   additive_tail: MapSet.new([]),
                   body_item_ep1: MapSet.new([]),
                   qualified_call_with_path: MapSet.new([]),
                   body_item: MapSet.new([]),
                   type_field: MapSet.new([]),
                   list: MapSet.new([]),
                   field_body_item: MapSet.new([]),
                   order_item_list: MapSet.new([:tail, :COMMA]),
                   when_clause: MapSet.new([]),
                   when_expr: MapSet.new([:when_clause]),
                   where_clause: MapSet.new([]),
                   predicate: MapSet.new([]),
                   rational: MapSet.new([]),
                   additive: MapSet.new([:additive_tail]),
                   primary: MapSet.new([]),
                   comp_op: MapSet.new([]),
                   mult_tail: MapSet.new([]),
                   shape_type: MapSet.new([]),
                   unary: MapSet.new([]),
                   subset_of_op: MapSet.new([]),
                   multiplicative: MapSet.new([:mult_tail]),
                   partition_clause: MapSet.new([]),
                   conjunction: MapSet.new([:right, :KW_AND]),
                   qualified_call: MapSet.new([]),
                   base_type: MapSet.new([]),
                   type_field_list: MapSet.new([:tail, :COMMA]),
                   superset_of_op: MapSet.new([]),
                   select: MapSet.new([]),
                   spread: MapSet.new([]),
                   subset_or_eq_op: MapSet.new([]),
                   path: MapSet.new([:tail, :DOT]),
                   in_lhs: MapSet.new([]),
                   fragment_or_comment: MapSet.new([]),
                   type_operand: MapSet.new([]),
                   type_kind: MapSet.new([]),
                   order_item: MapSet.new([]),
                   group_by_rollup: MapSet.new([]),
                   call_arg: MapSet.new([]),
                   type_param: MapSet.new([]),
                   superset_or_eq_op: MapSet.new([]),
                   union_tail: MapSet.new([]),
                   negation: MapSet.new([]),
                   frame_bound: MapSet.new([]),
                   disjunction: MapSet.new([:right, :KW_OR]),
                   distinct_clause: MapSet.new([]),
                   select_ep1a: MapSet.new([]),
                   having_clause: MapSet.new([]),
                   body_list_sep: MapSet.new([]),
                   group_by_cube: MapSet.new([]),
                   offset_clause: MapSet.new([]),
                   frame_clause: MapSet.new([]),
                   body_list: MapSet.new([]),
                   literal: MapSet.new([]),
                   comparison_ep1e: MapSet.new([]),
                   order_by_clause: MapSet.new([]),
                   field_name: MapSet.new([]),
                   call_args: MapSet.new([:tail, :COMMA]),
                   with_or_comment: MapSet.new([]),
                   field_list: MapSet.new([:tail, :COMMA]),
                   type_or_comment: MapSet.new([]),
                   required_clause: MapSet.new([]),
                   with_decl: MapSet.new([]),
                   expression: MapSet.new([:bitwise_tail]),
                   window_call: MapSet.new([]),
                   over_spec: MapSet.new([]),
                   fragment_decl: MapSet.new([]),
                   comparison: MapSet.new([]),
                   type_expr: MapSet.new([:union_tail]),
                   combinator_tail: MapSet.new([]),
                   list_type: MapSet.new([]),
                   limit_clause: MapSet.new([])
                 }) do
              {:ok, value, new_ctx} -> do_run_sequence(stream, new_pos, new_ctx, [value | acc])
              {:error, _} = err -> err
            end

          _fail ->
            {:error,
             Ichor.Error.new(
               message: "input does not match #{inspect(:document)}",
               stage: :parser
             )}
        end
      end
    end
  )
end
